def get_book_names():
    paths = [
        "templates/book_names.pkl",
        "artifacts/serialized_objects/book_names.pkl"
    ]
    for p in paths:
        if os.path.exists(p):
            with open(p, "rb") as f:
                return pickle.load(f)

    # If model is not yet trained, run training pipeline automatically
    with st.spinner("Initializing ML pipeline and generating dataset artifacts..."):
        pipeline = TrainingPipeline()
        pipeline.run_pipeline()

    if os.path.exists("templates/book_names.pkl"):
        with open("templates/book_names.pkl", "rb") as f:
            return pickle.load(f)
    return []
